window.AUTH=window.AUTH||{};window.AUTH["19-715"]={"d":"19-715","id":"2019/19-715","n":"Trump v. Mazars USA, LLP","briefs":[{"k":"petitioner","label":"Brief of petitioners Donald J. Trump, et al.","date":"2020-01-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/130092/20200127191622299_19-715%20and%2019-760%20Brief%20for%20Petitioners.pdf","side":"pet","n":83},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/130825/20200203173620062_19-715tsacUnitedStates.pdf","side":"us","n":30},{"k":"respondent","label":"Brief of respondents Committees of the U.S. House of Representatives","date":"2020-02-26","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/134253/20200226162318816_Nos%2019%20715%20760%20%20Merits%20Brief%20Final.pdf","side":"res","n":59},{"k":"reply","label":"Reply of petitioners Donald J. Trump, et al.","date":"2020-03-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/139285/20200327114310120_19-715%2019-760_Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=407","tr":true,"items":[{"t":"case","label":"Pages(s) Cases: Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"Article I, §8, grants Congress broad power to enact legislation in several enumerated areas of national concern.","cite":"527 U.S. 706, 731"}]},{"t":"case","label":"Anderson v. Dunn","cite":"19 U.S. 204","y":1821,"id":"1789-1850/19us204","sc":1,"by":{"0":"32, 33, 53","3":"4, 5, 26"},"q":[{"src":"brief","b":0,"text":"the genius and spirit of our institutions are hostile to the exercise of implied powers.","cite":"19 U.S. at 225"},{"src":"brief","b":0,"text":"‘the least possible power adequate to the end proposed.’","cite":"19 U.S. at 231"},{"src":"brief","b":3,"text":"the least possible power adequate to the end proposed.","cite":"19 U.S. at 230"}]},{"t":"case","label":"Armstrong v. Bush","cite":"924 F.2d 282","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/924/282/","by":{"0":"48, 57","2":"70"},"q":[{"src":"brief","b":0,"text":"the President must submit the disposal schedules to the appropriate congressional committees and wait sixty days before destroying the records.","cite":"924 F.2d 282, 286"},{"src":"brief","b":0,"text":"Although the ‘clear statement’ rule was originally articulated to guide interpretation of statutes that significantly alter the federal-state balance, there are similar compelling reasons to apply the rule to statutes that significantly alter the balance between Congress and the President.","cite":"924 F.2d at 289"}]},{"t":"case","label":"Ashland Oil, Inc. v. FTC","cite":"548 F.2d 977","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/548/977/","by":{"0":"62"},"q":[{"src":"brief","b":0,"text":"a violation of the House Rules","cite":"548 F.2d 977, 991"}]},{"t":"case","label":"Ashwander v. Tennessee Valley Auth.","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"by":{"0":"55"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"reduces [Article I] to a mere ‘parchment barrier against the encroaching spirit’ of legislative power.","cite":"136 S. Ct. 1310, 1336"},{"src":"argument","who":"Mr. Letter","text":"And, in fact, the -- the subpoena by the Intelligence Committee matches the subpoena from the Financial Services Committee to Deutsche Bank because, specifically, Intelligence did not want to cause too much of a burden to subpoena the --"},{"src":"argument","who":"Mr. Letter","text":"And last is there's massive public reporting about the -- the -- the subjects of these subpoenas and their banking practices, and Deutsche Bank and Capital One have both been sanctioned many millions of dollars by banking regulators for failing to properly comply with money laundering laws."}]},{"t":"case","label":"Barenblatt v. United States","cite":"360 U.S. 109","y":1959,"id":"1958/35","sc":1,"by":{"0":"36, 41, 43","2":"passim","3":"15, 19"},"q":[{"src":"brief","b":0,"text":"cannot inquire into matters which are within the exclusive province of one of the other branches,","cite":"360 U.S. 109, 111-12"},{"src":"brief","b":2,"text":"related to a valid legislative purpose.","cite":"360 U.S. 109, 127"},{"src":"brief","b":2,"text":"the Judiciary lacks authority to intervene on the basis of the motives which spurred the exercise of that power.","cite":"360 U.S. at 132"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"concern[ ] a subject on which legislation could be had.","cite":"360 U. S. 109, 127"},{"src":"argument","who":"Mr. Letter","text":"Your Honor, this -- this Court has explained in -- in quite a few cases -- I think Watkins, Barenblatt, others -- that the Congress's legislative power, which -- I mean investigative power, which stems from the British parliament's power, is an obvious and integral part of legislation."}]},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"33"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"by":{"0":"47-48, 58","1":"19","3":"24"},"q":[{"src":"brief","b":3,"text":"is inconsistent with separation of powers.","cite":"478 U.S. 714, 723"}]},{"t":"case","label":"Campbell v. Davidson","cite":"233 F.3d 1229","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/233/1229/","by":{"0":"49"}},{"t":"case","label":"Cheney v. U.S. Dist. Court for D.C.","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"0":"36, 53, 54","1":"15, 16, 24, 34","2":"63","3":"30"},"q":[{"src":"brief","b":1,"text":"in no case would a court be required to proceed against the president as against an ordinary individual.","cite":"542 U.S. 367, 382"},{"src":"brief","b":1,"text":"that might distract it from the energetic performance of its constitutional duties.","cite":"542 U.S. at 382"},{"src":"argument","who":"Mr. Strawbridge","text":"And then, of course, this Court in a number of cases, as we describe, has recognized, going back to Chief Justice Marshall, that we do not proceed against the President as we do against an ordinary litigant. And so whether that was in Cheney, whether that was the limiting construction given to the APA in --"}]},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"by":{"0":"47","3":"26"},"q":[{"src":"brief","b":3,"text":"aggrandizement of one branch at the expense of the other.","cite":"524 U.S. 417, 482"}]},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"by":{"0":"53, 64, 65","1":"1, 14, 15, 16, 20","2":"passim","3":"6, 12, 34"},"q":[{"src":"brief","b":0,"text":"‘the high respect that is owed to the office of the Chief Executive is a matter that should inform the conduct of the entire proceeding.’","cite":"520 U.S. 681, 707"},{"src":"brief","b":0,"text":"as well as the potential additional [subpoenas] that an affirmance of the Court of Appeals judgment might spawn—may impose an unacceptable burden on the … office,","cite":"520 U.S. at 701"},{"src":"brief","b":1,"text":"the essence of the constitutional principle,","cite":"520 U.S. 681, 714"},{"src":"brief","b":1,"text":"[t]he high respect that is owed to the office of the Chief Executive * * * should inform the conduct of the entire proceeding, including the timing and scope of discovery.","cite":"520 U.S. at 707"},{"src":"brief","b":2,"text":"impair[] … the Executive’s ability to perform its constitutionally mandated functions,","cite":"520 U.S. at 702"},{"src":"brief","b":2,"text":"never suggested that the President, or any other official, has an immunity that extends beyond the scope of any action taken in an official capacity.","cite":"520 U.S. at 694"},{"src":"brief","b":3,"text":"support a principle of the President’s independent authority to control his own time and energy.","cite":"520 U.S. at 711"}]},{"t":"case","label":"Comm. on Judiciary, U.S. House of Representatives v. Miers","cite":"558 F. Supp. 2d 53","y":2008,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/558/53/","by":{"0":"32"}},{"t":"case","label":"Eastland v. U.S. Servicemen’s Fund","cite":"421 U.S. 491","y":1975,"id":"1974/73-1923","sc":1,"by":{"0":"passim","1":"12, 22","2":"passim","3":"8, 21"},"q":[{"src":"brief","b":0,"text":"The subject of any inquiry always must be one ‘on which legislation could be had.’","cite":"421 U.S. at 504 n.15"},{"src":"brief","b":0,"text":"‘blind alleys’ and into nonproductive enterprises.","cite":"421 U.S. at 509"},{"src":"brief","b":2,"text":"intended to inform Congress in an area where legislation may be had.","cite":"421 U.S. 491, 506"},{"src":"brief","b":2,"text":"has often noted that the power to investigate is inherent in the power to make laws.","cite":"421 U.S. at 504"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"concern[ ] a subject on which legislation `could be had,'","cite":"421 U. S. 491, 506"},{"src":"argument","who":"Justice Sotomayor","text":"And in some of those cases, we have said, especially Eastland and McGrain, that a congressional subpoena is valid so long as there is a conceivable legislative purpose and the records are relevant to that purpose."},{"src":"argument","who":"Mr. Strawbridge","text":"With respect to the custodian issue, this Court, even going back to Eastland, has always recognized the ability of a person who stands in the President's whose records are in the hands of a third-party to come in and challenge them, and that's certainly the case here."},{"src":"argument","who":"Mr. Strawbridge","text":"-- not in Eastland."}]},{"t":"case","label":"Exxon Corp. v. FTC","cite":"589 F.2d 582","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/589/582/","by":{"0":"56"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"by":{"0":"50, 57, 59, 60","1":"15, 22","2":"69, 70","3":"32, 33"},"q":[{"src":"brief","b":3,"text":"‘each authority of the Government of the United States.’","cite":"505 U.S. 788, 800"},{"src":"argument","who":"Justice Breyer","text":"And the fact that what I hold today will also apply to a future Senator McCarthy asking a future Franklin Roosevelt or Harry Truman exactly the same questions, that bothers me."}]},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"32, 46, 47","1":"17, 19, 22","2":"55, 61"},"q":[{"src":"brief","b":0,"text":"Congress has plenary control over the salary, duties, and even existence of executive offices.","cite":"561 U.S. at 500"},{"src":"brief","b":0,"text":"power of appointing, overseeing, and controlling those who execute the laws.","cite":"561 U.S. at 492"},{"src":"brief","b":1,"text":"impair [the Executive] in the performance of its constitutional duties","cite":"561 U.S. at 500"},{"src":"brief","b":1,"text":"impair [the President] in the performance of [his] constitutional duties.","cite":"561 U.S. at 500"},{"src":"brief","b":2,"text":"in the performance of [his] constitutional duties.","cite":"561 U.S. at 500"}]},{"t":"case","label":"Gordon v. United States","cite":"117 U.S. 697","y":1864,"url":"https://supreme.justia.com/cases/federal/us/117/697/","sc":1,"by":{"0":"46"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"by":{"0":"61"},"q":[{"src":"brief","b":0,"text":"‘traditionally sensitive areas, … the requirement of clear statement assures that the legislature has in fact faced, and intended to bring into issue, the critical matters involved in the judicial decision.’","cite":"501 U.S. 452, 461"}]},{"t":"case","label":"Hearst v. Black","cite":"87 F.2d 68","y":1936,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/87/68/","by":{"0":"52"}},{"t":"case","label":"Hutcheson v. United States","cite":"369 U.S. 599","y":1962,"id":"1961/46","sc":1,"by":{"0":"37, 40, 42","2":"44, 48, 49, 53","3":"19, 20"},"q":[{"src":"brief","b":0,"text":"by publicity … exceeds the congressional power.","cite":"369 U.S. at 624"},{"src":"brief","b":0,"text":"far short of sustaining what [was] sought to be made of them.","cite":"369 U.S. at 619"},{"src":"brief","b":2,"text":"[J]ust as the Constitution forbids the Congress to enter fields reserved to the Executive and Judiciary, it imposes on the Judiciary the reciprocal duty of not lightly interfering with Congress’ exercise 45 Petitioners are also mistaken to suggest (at 58 n.6) that those powers derive from the Necessary and Proper Clause, U.S. Const. art. I, § 8, cl. 18, or 2 U.S.C. § 192, the statute making contempt of Congress a criminal offense. See McGrain, 273 U.S. at 175 (locating them in U.S. Const. art. I, § 1). of its legitimate powers.","cite":"369 U.S. 599, 622"},{"src":"brief","b":2,"text":"At most, Kilbourn is authority for the proposition that Congress cannot constitutionally inquire ‘into the private affairs of individuals who hold no office under the government’ when the investigation ‘could result in no valid legislation on the subject to which the inquiry referred.’","cite":"369 U.S. at 613 n.16"},{"src":"brief","b":3,"text":"the closest scrutiny to assure that indeed a legislative purpose was being pursued and that the inquiry was not aimed at aiding the criminal prosecution.","cite":"369 U.S. 599, 625"},{"src":"brief","b":3,"text":"committee which is engaged in a legitimate legislative investigation need not grind to a halt whenever responses to its inquiries might potentially be harmful to a witness in some distinct proceeding,","cite":"369 U.S. at 618"}]},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"0":"48, 58","1":"10, 17, 20, 33","3":"24"},"q":[{"src":"brief","b":0,"text":"legislative [in] character … in only one way; bicameral passage followed by presentment to the President.","cite":"462 U.S. at 954"},{"src":"brief","b":1,"text":"that the powers conferred on Congress were the powers to be most carefully circumscribed,","cite":"462 U.S. at 947"},{"src":"brief","b":3,"text":"independent of … the President, they did so in explicit, unambiguous terms.","cite":"462 U.S. 919, 955"}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"57","3":"5"},"q":[{"src":"brief","b":0,"text":"plain statement rule draws additional reinforcement from other canons of statutory construction.","cite":"533 U.S. 289, 299"}]},{"t":"case","label":"Judicial Watch, Inc. v. U.S. Secret Service","cite":"726 F.3d 208","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/726/208/","by":{"0":"48","1":"25"},"q":[{"src":"brief","b":0,"text":"avoid[s] the very separation of powers concerns","cite":"726 F.3d 208, 227-28"}]},{"t":"case","label":"Kilbourn v. Thompson","cite":"103 U.S. 168","y":1880,"id":"scdb/1880-103","sc":1,"by":{"0":"passim","1":"12","2":"44, 53","3":"6, 15, 17"},"q":[{"src":"brief","b":0,"text":"if the ‘gravamen’ of the investigation rests on ‘suspicions of criminality.’","cite":"103 U.S. 168, 193, 195"},{"src":"brief","b":0,"text":"the final judge of its own power and privileges,","cite":"103 U.S. at 199"},{"src":"brief","b":3,"text":"the powers appropriate to its own department and no other.","cite":"103 U.S. at 191"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"`not because it is a representative body with legislative functions, but by virtue of ancient usage and prescription . . . which forms a part of the common law of the land, and according to which the High Court of Parliament before its division, and the Houses of Lords and Commons since, are invested with many privileges, that of punishment for contempt being one.'","cite":"103 U. S., at 188"},{"src":"argument","who":"Mr. Strawbridge","text":"Well, in Kilbourn, this Court recognized that -- that -- that they're two very different powers and that -- and that when impeachment is properly pending before either body of the House, the ability to subpoena pursuant to impeachment is coextensive with that of a court."},{"src":"argument","who":"Mr. Strawbridge","text":"Well, setting aside any executive privilege concerns, which I understand is not -- not the focus of your question, the answer is because Congress has -- or this Court has repeatedly emphasized in Kilbourn and Watkins and everywhere else that Congress lacks any power to inquire into the private affairs of any individual."},{"src":"argument","who":"Mr. Strawbridge","text":"And, indeed, in numerous separation of powers cases, starting with Kilbourn, the Court has declined to extend any presumption that -- that -- that Congress had a legitimate power."}]},{"t":"case","label":"Kissinger v. Reporters Comm. for Freedom of the Press","cite":"445 U.S. 136","y":1980,"id":"1979/78-1088","sc":1,"by":{"0":"56"},"q":[{"src":"brief","b":0,"text":"the ‘Executive Office of the President’ … does not include the Office of the President","cite":"445 U.S. 136, 156"}]},{"t":"case","label":"La. Public Service Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"by":{"0":"47"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"by":{"0":"31","3":"5"},"q":[{"src":"brief","b":0,"text":"determination of ‘what the law is.’","cite":"5 U.S. 137, 177"}]},{"t":"case","label":"Marshall v. Gordon","cite":"243 U.S. 521","y":1917,"id":"scdb/1916-125","sc":1,"by":{"0":"33"},"q":[{"src":"argument","who":"Mr. Strawbridge","text":"And then, of course, this Court in a number of cases, as we describe, has recognized, going back to Chief Justice Marshall, that we do not proceed against the President as we do against an ordinary litigant."}]},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"by":{"0":"33, 35"},"q":[{"src":"brief","b":0,"text":"Chief Justice Marshall was emphatic that no ‘great substantive and independent power’ can be ‘implied as incidental to other powers, or used as a means of executing them.’","cite":"17 U.S. 316, 411"}]},{"t":"case","label":"McGrain v. Daugherty","cite":"273 U.S. 135","y":1927,"id":"1900-1940/273us135","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"seeks information sufficiently relevant to the Committee’s legislative inquiry.","cite":"273 U.S. 135, 177"},{"src":"brief","b":0,"text":"whether this power is so far incidental to the legislative function as to be implied.","cite":"273 U.S. at 161"},{"src":"brief","b":1,"text":"auxiliary powers as are necessary and appropriate to make the express powers effective.","cite":"273 U.S. 135, 173-174"},{"src":"brief","b":1,"text":"was so regarded in the British Parliament and in the Colonial legislatures before the American Revolution.","cite":"273 U.S. at 161"},{"src":"brief","b":2,"text":"before and when the Constitution was framed and adopted.","cite":"273 U.S. 135, 175"},{"src":"brief","b":2,"text":"Mr. Madison, who had taken an important part in framing the Constitution only five years before, and four of his associates in that work.","cite":"273 U.S. at 161"},{"src":"brief","b":3,"text":"subject to regulation by congressional legislation.","cite":"273 U.S. at 177"},{"src":"brief","b":3,"text":"might possibly disclose crime or wrongdoing on his part,","cite":"273 U.S. at 180"},{"src":"argument","who":"Justice Sotomayor","text":"And in some of those cases, we have said, especially Eastland and McGrain, that a congressional subpoena is valid so long as there is a conceivable legislative purpose and the records are relevant to that purpose."},{"src":"argument","who":"Mr. Letter","text":"First is this Court's decision in McGrain, which is -- is extremely important here. Now McGrain was not seeking papers of the President, but, there, the lower court struck down -- said the subpoena was no good, the congressional investigation was no good because it was inspired by politics."},{"src":"argument","who":"Mr. Letter","text":"First, McGrain, this Court said very, very clearly, you don't just look at the authorization. There was no authorization there. Second, yes, Section -- Resolution 507 is, in part, broadly worded, but it is extremely specific in its third \"whereas\" clause."}]},{"t":"case","label":"McPhaul v. United States","cite":"364 U.S. 372","y":1960,"id":"1960/33","sc":1,"by":{"0":"52","3":"28"}},{"t":"case","label":"McSurely v. McClellan","cite":"521 F.2d 1024","y":1975,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/521/1024/","by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"trench upon Executive or judicial prerogatives,","cite":"521 F.2d 1024, 1038"}]},{"t":"case","label":"Metzenbaum v. FERC","cite":"675 F.2d 1282","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/675/1282/","by":{"0":"56"},"q":[{"src":"brief","b":0,"text":"rights of persons other than members of Congress are jeopardized by Congressional failure to follow its own procedures.","cite":"675 F.2d 1282, 1287"}]},{"t":"case","label":"Michigan v. EPA","cite":"268 F.3d 1075","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/268/1075/","by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"no constitutional or common law existence or authority, but only those authorities conferred upon [them] by Congress.","cite":"268 F.3d 1075, 1081"}]},{"t":"case","label":"Mississippi v. Johnson","cite":"71 U.S. 475","y":1866,"id":"1850-1900/71us475","sc":1,"by":{"0":"50"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"0":"47","2":"43"},"q":[{"src":"brief","b":0,"text":"flexible understanding of separation of powers,","cite":"488 U.S. 361, 381"}]},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"by":{"0":"14, 44, 47, 59","1":"23","2":"1, 55"},"q":[{"src":"brief","b":0,"text":"With regard to the threat to the Presidency, this wolf comes as a wolf.’","cite":"487 U.S. 654, 699"},{"src":"brief","b":0,"text":"political branches are … in disagreement, neither can be presumed correct.","cite":"487 U.S. at 705"},{"src":"argument","who":"Mr. Strawbridge","text":"In -- in Morrison v. Olson as well, the Court did not apply a presumption on either side of that dispute precisely because it was a battle between the branches."}]},{"t":"case","label":"NAMUDNO v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"by":{"0":"61"},"q":[{"src":"brief","b":0,"text":"will not shrink from [its] duty as the bulwark of a limited constitution against legislative encroachments.","cite":"557 U.S. 193, 205"}]},{"t":"case","label":"NCTA v. United States","cite":"415 U.S. 336","y":1974,"url":"https://supreme.justia.com/cases/federal/us/415/336/","sc":1,"by":{"0":"58"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"32, 33, 51","3":"3, 6"},"q":[{"src":"brief","b":0,"text":"‘the most telling indication of [a] severe constitutional problem … is the lack of historical precedent’ for Congress’s action.","cite":"567 U.S. 519, 549"},{"src":"brief","b":0,"text":"undermine the structure of government established by the Constitution.","cite":"567 U.S. at 559"},{"src":"argument","who":"Mr. Strawbridge","text":"To begin, the subpoena power is an implied power, and this Court made clear, most recently in NFIB v. Sebelius, that Congress cannot use its implied powers to challenge the structure of government."}]},{"t":"case","label":"Nixon v. Adm’r of Gen. Servs.","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"by":{"0":"11","1":"21","2":"passim"},"q":[{"src":"brief","b":2,"text":"have no partial agency in, or no controul over the acts of each other.","cite":"433 U.S. at 442 n.5"}]},{"t":"case","label":"Nixon v. Fitzgerald","cite":"475 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"by":{"0":"passim","1":"passim","2":"60, 64","3":"6"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"by":{"0":"27, 31","2":"43, 62, 64","3":"9"},"q":[{"src":"brief","b":0,"text":"allocation of power between two elected branches of Government.","cite":"573 U.S. 513, 524"},{"src":"brief","b":0,"text":"‘is a consideration of great weight in a proper interpretation of constitutional provisions regulating the relationship between Congress and the President.","cite":"573 U.S. at 524"},{"src":"brief","b":3,"text":"allocation of power between two elected branches of government.","cite":"573 U.S. 513, 524"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the compromises and working arrangements that [those] branches . . . themselves have reached.","cite":"573 U. S. 513, 524– 526"}]},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"0":"31","3":"13, 23"},"q":[{"src":"brief","b":0,"text":"dated back to ‘the beginning of the Republic,’ and included ‘thousands of intra-session recess appointments.’","cite":"137 S. Ct. 929, 943"},{"src":"brief","b":3,"text":"‘Neither Congress nor the Executive can agree to waive’ the structural provisions of the Constitution any more than they could agree to disregard an enumerated right.","cite":"137 S.Ct. at 949"}]},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"by":{"0":"24, 31, 33"},"q":[{"src":"brief","b":0,"text":"that the power was thought not to exist.","cite":"521 U.S. 898, 905"},{"src":"brief","b":0,"text":"of a constitutional tradition that lends meaning to the text.","cite":"521 U.S. at 917"}]},{"t":"case","label":"Quinn v. United States","cite":"349 U.S. 155","y":1955,"id":"scdb/1954-078","sc":1,"by":{"0":"36, 37, 45","1":"11, 13, 26","2":"42, 45","3":"19"},"q":[{"src":"brief","b":0,"text":"any of the powers of law enforcement; those powers are assigned under our Constitution to the Executive and the Judiciary.","cite":"349 U.S. 155, 161"},{"src":"brief","b":0,"text":"the power to investigate … cannot be used to inquire into private affairs unrelated to a valid legislative purpose.","cite":"349 U.S. at 161"},{"src":"brief","b":1,"text":"those powers are assigned under our Constitution to the Executive and the Judiciary.","cite":"349 U.S. at 161"},{"src":"brief","b":1,"text":"be used to inquire into private affairs unrelated to a valid legislative purpose,","cite":"349 U.S. at 161"},{"src":"brief","b":2,"text":"deeply rooted in American and English institutions.","cite":"349 U.S. 155, 160-61"},{"src":"brief","b":2,"text":"co-extensive with the power to legislate,","cite":"349 U.S. at 160"},{"src":"brief","b":3,"text":"any of the powers of law enforcement; those powers are assigned under our Constitution to the Executive and the Judiciary.","cite":"349 U.S. 155, 161"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"those powers are assigned under our Constitution to the Executive and the Judiciary.","cite":"349 U. S., at 161"}]},{"t":"case","label":"Schaefer v. Townsend","cite":"215 F.3d 1031","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/215/1031/","by":{"0":"49","3":"25"}},{"t":"case","label":"Senate Select Comm. v. Nixon","cite":"498 F.2d 725","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/498/725/","by":{"0":"30, 40, 53","1":"23, 24, 28, 30","2":"67","3":"28"},"q":[{"src":"brief","b":3,"text":"that the President is required to comply with the … subpoena[s].","cite":"498 F.2d 725, 732-33"},{"src":"argument","who":"Mr. Strawbridge","text":"Circuit recognized in Senate Select Committee and Judge Livingston recognized below, most often, that's going to take the view of forward-looking information, perhaps aggregated information, and not an attempt to, you know, reassemble a precise factual history --"},{"src":"argument","who":"Mr. Strawbridge","text":"And, indeed, in numerous separation of powers cases, starting with Kilbourn, the Court has declined to extend any presumption that -- that -- that Congress had a legitimate power. That was also true below in the D.C. Circuit in Tobin, in the Senate Select Committee case, and even in the AT&T cases."},{"src":"argument","who":"Mr. Wall","text":"Well, this particular question hasn't come up to the Court before in a constitutional context, but, in Nixon, of course, the prosecutor had to show, demonstrate a specific need. In the Senate Select Committee case --"}]},{"t":"case","label":"Sinclair v. United States","cite":"279 U.S. 263","y":1929,"id":"scdb/1928-056","sc":1,"by":{"0":"42","2":"47, 48","3":"19, 20"},"q":[{"src":"brief","b":0,"text":"contention that the investigation was avowedly not in aid of legislation","cite":"279 U.S. at 295"},{"src":"brief","b":2,"text":"in direct furtherance of [a] legislative purpose.","cite":"279 U.S. 263"},{"src":"brief","b":2,"text":"passed a joint resolution ‘reciting that [oil tycoon Harry Sinclair’s] leases were executed under circumstances indicating fraud and corruption’ and ‘directing the President to prosecute such [cases], as were warranted by the facts.’","cite":"279 U.S. at 289"}]},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"by":{"0":"27","2":"44"},"q":[{"src":"brief","b":0,"text":"Congress was acting outside its legislative role,","cite":"341 U.S. 367, 377"},{"src":"brief","b":2,"text":"[t]o find that a committee’s investigation has exceeded the bounds of legislative power it must be obvious that there was a usurpation of functions exclusively vested","cite":"341 U.S. 367, 378"},{"src":"brief","b":2,"text":"[c]ourts are not the place for such controversies.","cite":"341 U.S. at 378"}]},{"t":"case","label":"Tobin v. United States","cite":"306 F.2d 270","y":1962,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/306/270/","by":{"0":"45, 61","1":"22, 33","3":"23"},"q":[{"src":"brief","b":0,"text":"to conduct such a novel investigation it would have spelled out this intention in words more explicit than the general terms found in the authorizing resolutions under consideration.","cite":"306 F.2d at 275"},{"src":"argument","who":"Mr. Strawbridge","text":"And, indeed, in numerous separation of powers cases, starting with Kilbourn, the Court has declined to extend any presumption that -- that -- that Congress had a legitimate power. That was also true below in the D.C. Circuit in Tobin, in the Senate Select Committee case, and even in the AT&T cases."}]},{"t":"case","label":"U.S. Term Limits, Inc. v. Thornton","cite":"514 U.S. 779","y":1995,"id":"1994/93-1456","sc":1,"by":{"0":"48, 49","2":"57","3":"25"},"q":[{"src":"brief","b":0,"text":"constitutional rights would be of little value if they could be indirectly denied.","cite":"514 U.S. at 829"},{"src":"brief","b":2,"text":"the likely effect of handicapping a class of candidates,","cite":"514 U.S. at 836"},{"src":"brief","b":2,"text":"it has the likely effect of handicapping a class of candidates and has the sole purpose of creating additional qualifications indirectly.","cite":"514 U.S. at 836"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"[o]ur system of government rests on one overriding principle: All power stems from the consent of the people.","cite":"514 U. S. 779, 846"}]},{"t":"case","label":"United States ex rel. Attorney General v. Delaware & Hudson Co.","cite":"213 U.S. 366","y":1909,"id":"scdb/1908-137","sc":1,"by":{"0":"57"}},{"t":"case","label":"United States v. Ballin","cite":"144 U.S. 1","y":1892,"id":"scdb/1891-140","sc":1,"by":{"0":"56"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"0":"57"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 187","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/187/","by":{"0":"53"},"q":[{"src":"brief","b":0,"text":"‘in no case of this kind would a court be required to proceed against the president as against an ordinary individual.’","cite":"25 F. Cas. 187, 192"}]},{"t":"case","label":"United States v. Kebodeaux","cite":"570 U.S. 387","y":2013,"id":"2012/12-418","sc":1,"by":{"0":"33, 34, 35","3":"6"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"0":"53","1":"15","2":"passim","3":"33"},"q":[{"src":"brief","b":2,"text":"court [should not] proceed against the president as against an ordinary individual.","cite":"418 U.S. 683, 708"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"fundamental to the operation of Government.","cite":"418 U. S., at 708"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"full disclosure of all the facts,","cite":"418 U. S., at 709"}]},{"t":"case","label":"United States v. Rumely","cite":"345 U.S. 41","y":1953,"id":"scdb/1952-055","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"32"},"q":[{"src":"brief","b":0,"text":"must first be settled before [the Court] may consider whether Congress had the power to confer upon the committee the authority which it claimed.","cite":"345 U.S. at 43"},{"src":"brief","b":0,"text":"outer reaches of Congress’s investigative power are to be identified reluctantly, and only after [it] ‘has demonstrated full awareness of what is at stake by unequivocally authorizing an inquiry of dubious limits.’","cite":"345 U.S. at 46"},{"src":"brief","b":1,"text":"demonstrated its full awareness of what is at stake,","cite":"345 U.S. 41, 46"},{"src":"brief","b":1,"text":"the controlling charter of the committee’s powers","cite":"345 U.S. 41, 44"},{"src":"brief","b":2,"text":"of books of a particular political tendentiousness.","cite":"345 U.S. at 47, 42"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"It is the proper duty of a representative body to look diligently into every affair of government and to talk much about what it sees. It is meant to be the eyes and the voice, and to embody the wisdom and will of its constituents. Unless Congress have and use every means of acquainting itself with the acts and the disposition of the administrative agents of the government, the country must be helpless to learn how it is being served.","cite":"345 U. S. 41, 43"},{"src":"argument","who":"Mr. Strawbridge","text":"Well, if I can answer that last question first, I think that the Court cannot refuse to see what others see, to quote Rumely, and -- and the -- the -- the threat in this case of subpoenaing, you know, decades worth of papers, not only of the President but of the President's family members, of his children, of his grandchildren, as the House has done in this case, poses an obvious problem with respect to harassment and infringement upon the ability of the executive to discharge his duties 24 hours a day."},{"src":"argument","who":"Mr. Wall","text":"It can't satisfy any standard sensitive to Article II and the separation of powers, and, indeed, as in Rumely and Watkins, this Court should not decide a serious constitutional question the full House itself has not confronted."},{"src":"argument","who":"Mr. Wall","text":"It falls short then even of the fairly meager resolutions in Rumely and Watkins, which at least described general purposes, general legislative topics."}]},{"t":"case","label":"xiv United States v. Welden","cite":"377 U.S. 95","y":1964,"id":"1963/235","sc":1,"by":{"0":"43"}},{"t":"case","label":"Watkins v. United States","cite":"354 U.S. 178","y":1957,"id":"1956/261","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"15, 17, 19, 32"},"q":[{"src":"brief","b":0,"text":"sensitive task of ensuring that Congress, in seeking the President’s personal information in aid of legislation, has employed ‘procedures which prevent the separation of power from responsibility.’","cite":"354 U.S. 178, 215"},{"src":"brief","b":0,"text":"There was very little use of the power of compulsory process in early years to enable the Congress to obtain facts pertinent to the enactment of new statutes or the administration of existing laws.","cite":"354 U.S. at 192"},{"src":"brief","b":1,"text":"justified solely as an adjunct to the legislative process.","cite":"354 U.S. 178, 197"},{"src":"brief","b":1,"text":"in furtherance of [] a legitimate task of the Congress.","cite":"354 U.S. at 187"},{"src":"brief","b":2,"text":"encompasses inquiries concerning the administration of existing laws as well as proposed or possibly needed statutes.","cite":"354 U.S. at 187"},{"src":"brief","b":2,"text":"Nor is the Congress a law enforcement or trial agency.","cite":"354 U.S. at 187"},{"src":"brief","b":3,"text":"beyond the powers conferred upon [it] in the Constitution,","cite":"354 U.S. at 198"},{"src":"brief","b":3,"text":"must be clearly revealed in its charter,","cite":"354 U.S. at 198"},{"src":"argument","who":"Mr. Strawbridge","text":"I think that there might be limited powers in some cases for the House to subpoena private documents, although the Court has been very clear in Watkins and a number of other cases that Congress lacks any power to just inquire --"},{"src":"argument","who":"Mr. Strawbridge","text":"Well, setting aside any executive privilege concerns, which I understand is not -- not the focus of your question, the answer is because Congress has -- or this Court has repeatedly emphasized in Kilbourn and Watkins and everywhere else that Congress lacks any power to inquire into the private affairs of any individual."},{"src":"argument","who":"Mr. Strawbridge","text":"These are the kinds of subpoenas that the Court in Watkins said raise specific questions about whether they're really attempting to expose alleged wrongdoing as opposed to achieve a valid legislative end."}]},{"t":"case","label":"Wilkinson v. United States","cite":"365 U.S. 399","y":1961,"id":"1960/37","sc":1,"by":{"0":"40","2":"51","3":"15"}},{"t":"case","label":"Yellin v. United States","cite":"374 U.S. 109","y":1963,"id":"1961/35","sc":1,"by":{"0":"56, 62"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"by":{"0":"33","3":"12"}},{"t":"const","label":"Article I, Section 5, Clause 2","text":"Each House may determine the Rules of its Proceedings, punish its Members for disorderly Behaviour, and, with the Concurrence of two thirds, expel a Member.","by":{"0":"2, 25","2":"12, 40, 62, 70"}},{"t":"const","label":"Article I, Section 8","by":{"0":"2, 46"}},{"t":"const","label":"Article I, Section 8, Clause 18","clauses":[["necessary-proper","Necessary and Proper Clause"]],"text":"To make all Laws which shall be necessary and proper for carrying into Execution the foregoing Powers, and all other Powers vested by this Constitution in the Government of the United States, or in any Department or Officer thereof.","by":{"0":"58","2":"43"}},{"t":"const","label":"Article I, Section 9","clauses":[["habeas","Suspension Clause (Habeas Corpus)"],["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"],["appropriations","Appropriations Clause"],["emoluments","Emoluments Clauses"]],"by":{"0":"51"}},{"t":"const","label":"Article I, Section 9, Clause 8","clauses":[["emoluments","Emoluments Clauses"]],"text":"No Title of Nobility shall be granted by the United States: And no Person holding any Office of Profit or Trust under them, shall, without the Consent of the Congress, accept of any present, Emolument, Office, or Title, of any kind whatever, from any King, Prince, or foreign State.","by":{"0":"2, 50","2":"29, 56"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"0":"2"}},{"t":"const","label":"Article II, Section 1, Clause 7","text":"The President shall, at stated Times, receive for his Services, a Compensation, which shall neither be encreased nor diminished during the Period for which he shall have been elected, and he shall not receive within that Period any other Emolument from the United States, or any of them.","by":{"0":"2, 50","2":"29"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"0":"2"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"2"}},{"t":"usc","label":"2 U.S.C. § 192","url":"https://www.law.cornell.edu/uscode/text/2/192","stext":{"head":"§192. Refusal of witness to testify or produce papers","paras":[[0,"Every person who having been summoned as a witness by the authority of either House of Congress to give testimony or to produce papers upon any matter under inquiry before either House, or any joint committee established by a joint or concurrent resolution of the two Houses of Congress, or any committee of either House of Congress, willfully makes default, or who, having appeared, refuses to answer any question pertinent to the question under inquiry, shall be deemed guilty of a misdemeanor, punishable by a fine of not more than $1,000 nor less than $100 and imprisonment in a common jail for not less than one month nor more than twelve months."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/192?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 58","2":"43, 45, 68"},"q":[{"src":"brief","b":2,"text":"a clear chain of authority from the House to the questioning body is an essential element of the offense","cite":"2 U.S.C. § 192"}]},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(1)"],"by":{"0":"59"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(b)(1)"],"by":{"0":"59"}},{"t":"usc","label":"5 U.S.C. § 7342","url":"https://www.law.cornell.edu/uscode/text/5/7342","subs":["(a)","(a)(1)(E)"],"stext":{"head":"§7342. Receipt and disposition of foreign gifts and decorations","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) \"employee\" means—"],[2,"(A) an employee as defined by section 2105 of this title and an officer or employee of the United States Postal Service or of the Postal Regulatory Commission;"],[2,"(B) an expert or consultant who is under contract under section 3109 of this title with the United States or any agency, department, or establishment thereof, including, in the case of an organization performing services under such section, any individual involved in the performance of such services;"],[2,"(C) an individual employed by, or occupying an office or position in, the government of a territory or possession of the United States or the government of the District of Columbia;"],[2,"(D) a member of a uniformed service;"],[2,"(E) the President and the Vice President;"],[2,"(F) a Member of Congress as defined by section 2106 of this title (except the Vice President) and any Delegate to the Congress; and"],[2,"(G) the spouse of an individual described in subparagraphs (A) through (F) (unless such individual and his or her spouse are separated) or a dependent (within the meaning of section 152 of the Internal Revenue Code of 1986) of such an individual, other than a spouse or dependent who is an employee under subparagraphs (A) through (F);"],[1,"(2) \"foreign government\" means—"],[2,"(A) any unit of foreign governmental authority, including any foreign national, State, local, and municipal government;"],[2,"(B) any international or multinational organization whose membership is composed of any unit of foreign government described in subparagraph (A); and"],[2,"(C) any agent or representative of any such unit or such organization, while acting as such;"],[1,"(3) \"gift\" means a tangible or intangible present (other than a decoration) tendered by, or received from, a foreign government;"],[1,"(4) \"decoration\" means an order, device, medal, badge, insignia, emblem, or award tendered by, or received from, a foreign government;"],[1,"(5) \"minimal value\" means a retail value in the United States at the time of acceptance of $100 or less, except that—"],[2,"(A) on January 1, 1981, and at 3 year intervals thereafter, \"minimal value\" shall be redefined in regulations prescribed by the Administrator of General Services, in consultation with the Secretary of State, to reflect changes in the consumer price index for the immediately preceding 3-year period; and"],[2,"(B) regulations of an employing agency may define \"minimal value\" for its employees to be less than the value established under this paragraph; and"],[1,"(6) \"employing agency\" means—"],[2,"(A) the Committee on Standards of Official Conduct of the House of Representatives, for Members and employees of the House of Representatives, except that those responsibilities specified in subsections (c)(2)(A), (e)(1), and (g)(2)(B) shall be carried out by the Clerk of the House;"],[2,"(B) the Select Committee on Ethics of the Senate, for Senators and employees of the Senate, except that those responsibilities (other than responsibilities involving approval of the employing agency) specified in subsections (c)(2), (d), and (g)(2)(B) shall be carried out by the Secretary of the Senate;"],[2,"(C) the Administrative Office of the United States Courts, for judges and judicial branch employees; and"],[2,"(D) the department, agency, office, or other entity in which an employee is employed, for other legislative branch employees and for all executive branch employees."],[0,"(b) An employee may not—"],[1,"(1) request or otherwise encourage the tender of a gift or decoration; or"],[1,"(2) accept a gift or decoration, other than in accordance with the provisions of subsections (c) and (d)."],[0,"(c)(1) The Congress consents to—"],[1,"(A) the accepting and retaining by an employee of a gift of minimal value tendered and received as a souvenir or mark of courtesy; and"],[1,"(B) the accepting by an employee of a gift of more than minimal value when such gift is in the nature of an educational scholarship or medical treatment or when it appears that to refuse the gift would likely cause offense or embarrassment or otherwise adversely affect the foreign relations of the United States, except that—"],[2,"(i) a tangible gift of more than minimal value is deemed to have been accepted on behalf of the United States and, upon acceptance, shall become the property of the United States; and"],[2,"(ii) an employee may accept gifts of travel or expenses for travel taking place entirely outside the United States (such as transportation, food, and lodging) of more than minimal value if such acceptance is appropriate, consistent with the interests of the United States, and permitted by the employing agency and any regulations which may be prescribed by the employing agency."],[0,"(2) Within 60 days after accepting a tangible gift of more than minimal value (other than a gift described in paragraph (1)(B)(ii)), an employee shall—"],[1,"(A) deposit the gift for disposal with his or her employing agency; or"],[1,"(B) subject to the approval of the employing agency, deposit the gift with that agency for official use."],[0,"Within 30 days after terminating the official use of a gift under subparagraph (B), the employing agency shall forward the gift to the Administrator of General Services in accordance with subsection (e)(1) or provide for its disposal in accordance with subsection (e)(2)."],[0,"(3) When an employee deposits a gift of more than minimal value for disposal or for official use pursuant to paragraph (2), or within 30 days after accepting travel or travel expenses as provided in paragraph (1)(B)(ii) unless such travel or travel expenses are accepted in accordance with specific instructions of his or her employing agency, the employee shall file a statement with his or her employing agency or its delegate containing the information prescribed in subsection (f) for that gift."],[0,"(d) The Congress consents to the accepting, retaining, and wearing by an employee of a decoration tendered in recognition of active field service in time of combat operations or awarded for other outstanding or unusually meritorious performance, subject to the approval of the employing agency of such employee. Without this approval, the decoration is deemed to have been accepted on behalf of the United States, shall become the property of the United States, and shall be deposited by the employee, within sixty days of acceptance, with the employing agency for official use, for forwarding to the Administrator of General Services for disposal in accordance with subsection (e)(1), or for disposal in accordance with subsection (e)(2)."],[0,"(e)(1) Except as provided in paragraph (2), gifts and decorations that have been deposited with an employing agency for disposal shall be (A) returned to the donor, or (B) forwarded to the Administrator of General Services for transfer, donation, or other disposal in accordance with the provisions of subtitle I of title 40 and division C (except sections 3302, 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41. However, no gift or decoration that has been deposited for disposal may be sold without the approval of the Secretary of State, upon a determination that the sale will not adversely affect the foreign relations of the United States. Gifts and decorations may be sold by negotiated sale."],[0,"(2) Gifts and decorations received by a Senator or an employee of the Senate that are deposited with the Secretary of the Senate for disposal, or are deposited for an official use which has terminated, shall be disposed of by the Commission on Arts and Antiquities of the United States Senate. Any such gift or decoration may be returned by the Commission to the donor or may be transferred or donated by the Commission, subject to such terms and conditions as it may prescribe, (A) to an agency or instrumentality of (i) the United States, (ii) a State, territory, or possession of the United States, or a political subdivision of the foregoing, or (iii) the District of Columbia, or (B) to an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 which is exempt from taxation under section 501(a) of such Code. Any such gift or decoration not disposed of as provided in the preceding sentence shall be forwarded to the Administrator of General Services for disposal in accordance with paragraph (1). If the Administrator does not dispose of such gift or decoration within one year, he shall, at the request of the Commission, return it to the Commission and the Commission may dispose of such gift or decoration in such manner as it considers proper, except that such gift or decoration may be sold only with the approval of the Secretary of State upon a determination that the sale will not adversely affect the foreign relations of the United States."],[0,"(f)(1) Not later than January 31 of each year, each employing agency or its delegate shall compile a listing of all statements filed during the preceding year by the employees of that agency pursuant to subsection (c)(3) and shall transmit such listing to the Secretary of State who shall publish a comprehensive listing of all such statements in the Federal Register."],[0,"(2) Such listings shall include for each tangible gift reported—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7342?type=usc&year=mostrecent&link-type=html"},"by":{"0":"51","2":"54"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1, 2"}},{"t":"usc","label":"44 U.S.C. § 2203","url":"https://www.law.cornell.edu/uscode/text/44/2203","subs":["(c)","(d)"],"by":{"0":"48, 48, 48"}},{"t":"case","label":"Bellis v. United States","cite":"417 U.S. 85","y":1974,"id":"1973/73-190","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"‘assume[s] the rights, duties and privileges’","cite":"417 U.S. 85, 89-90"}]},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"are replete with expressions of fear that the Legislative Branch * * * will aggrandize itself at the expense of the other two branches,","cite":"424 U.S. 1, 129"}]},{"t":"case","label":"Ford v. United States","cite":"273 U.S. 593","y":1927,"id":"scdb/1926-171","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"The general rule of the law is, that what one does through another’s agency is to be regarded as done by himself.","cite":"273 U.S. 593, 623"}]},{"t":"case","label":"Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"by":{"1":"25"}},{"t":"case","label":"Ho Ah Kow v. Nunan","cite":"12 F. Cas. 252","y":1879,"court":"C.C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Cas./12/252/","by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"[w]hen we take our seats on the bench we are not struck with blindness, and forbidden to know as judges what we see as men.","cite":"12 F. Cas. 252, 255"}]},{"t":"case","label":"Hutchinson v. Proxmire","cite":"443 U.S. 111","y":1979,"id":"1978/78-680","sc":1,"by":{"1":"12"}},{"t":"case","label":"Powell v. McCormack","cite":"395 U.S. 486","y":1969,"id":"1968/138","sc":1,"by":{"1":"27"}},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"by":{"1":"33"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"The Constitution deals with substance, not shadows.","cite":"559 U.S. 700, 723"}]},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"by":{"1":"19","2":"1"},"q":[{"src":"brief","b":1,"text":"In drama, magnitude and finality his decisions so far overshadow any others that almost alone he fills the public eye and ear.","cite":"343 U.S. 579, 653"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"[d]eeply embedded traditional way[ ] of conducting government.","cite":"343 U. S., at 610"}]},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","by":{"1":"25"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"by":{"2":"69"}},{"t":"case","label":"Chicago & N. W. Ry. Co. v. United Transp. Union","cite":"402 U.S. 570","y":1971,"id":"1970/189","sc":1,"by":{"2":"57"}},{"t":"case","label":"Dellums v. Powell","cite":"561 F.2d 242","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/561/242/","by":{"2":"67"}},{"t":"case","label":"Forrester v. White","cite":"484 U.S. 219","y":1988,"id":"1987/86-761","sc":1,"by":{"2":"60"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"by":{"2":"43","3":"5"},"q":[{"src":"brief","b":2,"text":"[T]his is precisely the type of ahistorical literalism that [this Court] ha[s] rejected[.]","cite":"139 S. Ct. 1485, 1498"},{"src":"argument","who":"Mr. Letter","text":"And this Court has said, for instance, most recently in Franchise Tax Board, that just because a power is -- is something to be implied doesn't mean that it's not important."}]},{"t":"case","label":"Glossip v. Gross","cite":"135 S. Ct. 2726","y":2015,"id":"2014/14-7955","sc":1,"by":{"2":"50","3":"19"}},{"t":"case","label":"Gojack v. United States","cite":"384 U.S. 702","y":1966,"id":"1965/594","sc":1,"by":{"2":"67, 68, 71"},"q":[{"src":"brief","b":2,"text":"[n]o committee of either the House or Senate … is free on its … own to conduct investigations unless authorized","cite":"384 U.S. 702, 716"},{"src":"brief","b":2,"text":"from the viewpoint not of the legislative process, but of the administration of criminal justice.","cite":"384 U.S. at 714"}]},{"t":"case","label":"Goldwater v. Carter","cite":"444 U.S. 996","y":1979,"id":"1979/79-856","sc":1,"by":{"2":"64"},"q":[{"src":"brief","b":2,"text":"has resources available to protect and assert [his] interests, resources not available to private litigants outside the judicial forum.","cite":"444 U.S. 996, 1004"}]},{"t":"case","label":"People ex rel. McDonald v. Keeler","cite":"99 N.Y. 463","y":1885,"url":"https://www.courtlistener.com/c/N.Y./99/463/","by":{"2":"52"},"q":[{"src":"brief","b":2,"text":"[w]e are bound to presume that the action of the legislative body was with a legitimate object, if it is capable of being so construed.","cite":"99 N.Y. 463, 487"}]},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"2":"72"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","by":{"2":"62"}},{"t":"case","label":"United States v. Centennial Builders, Inc.","cite":"747 F.2d 678","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/678/","by":{"2":"65"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"2":"69"},"q":[{"src":"brief","b":2,"text":"[r]ead naturally, the word ‘any’ has an expansive meaning, that is, ‘one or some indiscriminately of whatever kind.’","cite":"520 U.S. 1, 5"}]},{"t":"case","label":"United States v. Miller","cite":"425 U.S. 435","y":1976,"id":"1975/74-1179","sc":1,"by":{"2":"64, 65"},"q":[{"src":"brief","b":2,"text":"fall within a protected zone of privacy.","cite":"425 U.S. 435, 440"}]},{"t":"case","label":"United States v. R. Enters., Inc.","cite":"498 U.S. 292","y":1991,"id":"1990/89-1436","sc":1,"by":{"2":"54"},"q":[{"src":"brief","b":2,"text":"there is no reasonable possibility that the category of materials [sought] will produce information relevant to the general subject of the … investigation.","cite":"498 U.S. 292, 300-01"}]},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"2":"3, 42, 43","3":"6"}},{"t":"const","label":"Article I, Section 6, Clause 1","clauses":[["speech-debate","Speech or Debate Clause"]],"text":"The Senators and Representatives shall receive a Compensation for their Services, to be ascertained by Law, and paid out of the Treasury of the United States. They shall in all Cases, except Treason, Felony and Breach of the Peace, be privileged from Arrest during their Attendance at the Session of their respective Houses, and in going to and returning from the same; and for any Speech or Debate in either House, they shall not be questioned in any other Place.","by":{"2":"60, 61"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"2":"3"}},{"t":"const","label":"Article II, Section 1, Clause 5","clauses":[["natural-born","Natural-Born Citizen Clause"]],"text":"No Person except a natural born Citizen, or a Citizen of the United States, at the time of the Adoption of this Constitution, shall be eligible to the Office of President; neither shall any Person be eligible to that Office who shall not have attained to the Age of thirty five Years, and been fourteen Years a Resident within the United States.","by":{"2":"57"}},{"t":"const","label":"Amendment XXV, Section 4","text":"Whenever the Vice President and a majority of either the principal officers of the executive departments or of such other body as Congress may by law provide, transmit to the President pro tempore of the Senate and the Speaker of the House of Representatives their written declaration that the President is unable to discharge the powers and duties of his office, the Vice President shall immediately assume the powers and duties of the office as Acting President. Thereafter, when the President transmits to the President pro tempore of the Senate and the Speaker of the House of Representatives his written declaration that no inability exists, he shall resume the powers and duties of his office unless the Vice President and a majority of either the principal officers of the executive department or of such other body as Congress may by law provide, transmit within four days to the President pro tempore of the Senate and the Speaker of the House of Representatives their written declaration that the President is unable to discharge the powers and duties of his office. Thereupon Congress shall decide the issue, assembling within forty-eight hours for that purpose if not in session. If the Congress, within twenty-one days after receipt of the latter written declaration, or, if Congress is not in session, within twenty-one days after Congress is required to assemble, determines by two-thirds vote of both Houses that the President is unable to discharge the powers and duties of his office, the Vice President shall continue to discharge the same as Acting President; otherwise, the President shall resume the powers and duties of his office.","by":{"2":"56"}},{"t":"usc","label":"2 U.S.C. § 682","url":"https://www.law.cornell.edu/uscode/text/2/682","by":{"2":"55"}},{"t":"usc","label":"12 U.S.C. § 1829b","url":"https://www.law.cornell.edu/uscode/text/12/1829b","subs":["(a)"],"by":{"2":"65"}},{"t":"usc","label":"18 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/18/431","stext":{"head":"§431. Contracts by Member of Congress","paras":[[0,"Whoever, being a Member of or Delegate to Congress, or a Resident Commissioner, either before or after he has qualified, directly or indirectly, himself, or by any other person in trust for him, or for his use or benefit, or on his account, undertakes, executes, holds, or enjoys, in whole or in part, any contract or agreement, made or entered into in behalf of the United States or any agency thereof, by any officer or person authorized to make contracts on its behalf, shall be fined under this title."],[0,"All contracts or agreements made in violation of this section shall be void; and whenever any sum of money is advanced by the United States or any agency thereof, in consideration of any such contract or agreement, it shall forthwith be repaid; and in case of failure or refusal to repay the same when demanded by the proper officer of the department or agency under whose authority such contract or agreement shall have been made or entered into, suit shall at once be brought against the person so failing or refusing and his sureties for the recovery of the money so advanced."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/431?type=usc&year=mostrecent&link-type=html"},"by":{"2":"56"},"q":[{"src":"brief","b":2,"text":"the United States or any agency thereof.","cite":"18 U.S.C. § 431"}]},{"t":"usc","label":"22 U.S.C. § 9511","url":"https://www.law.cornell.edu/uscode/text/22/9511","by":{"2":"55"}},{"t":"usc","label":"31 U.S.C. § 5311","url":"https://www.law.cornell.edu/uscode/text/31/5311","by":{"2":"14"}},{"t":"usc","label":"31 U.S.C. § 5318","url":"https://www.law.cornell.edu/uscode/text/31/5318","subs":["(g)(2)(A)(i)","(h)(1)"],"by":{"2":"65, 18"}},{"t":"rule","label":"Fed. R. Crim. P. 17","url":"https://www.law.cornell.edu/rules/frcrmp/rule_17","subs":["(c)"],"by":{"2":"41, 58, 69"}},{"t":"case","label":"Coleman v. Miller","cite":"307 U.S. 433","y":1939,"id":"1900-1940/307us433","sc":1,"by":{"3":"5"}},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"by":{"3":"12, 15"},"q":[{"src":"brief","b":3,"text":"been open, widespread, and unchallenged since the early days of the Republic.","cite":"139 S. Ct. 2551, 2567"}]},{"t":"case","label":"Guerrero-Lasprilla v. Barr, --- S. Ct. ---","cite":"2020 WL 1325822","y":2020,"court":"Mar. 23","by":{"3":"19"}},{"t":"case","label":"Hewitt v. Helms","cite":"482 U.S. 755","y":1987,"id":"1986/85-1630","sc":1,"by":{"3":"22"},"q":[{"src":"brief","b":3,"text":"the settling of some dispute which affects the behavior of the defendant towards the plaintiff.","cite":"482 U.S. 755, 761"}]},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"by":{"3":"6"}},{"t":"case","label":"Northern Ins. Co. of N.Y. v. Chatham County, Ga.","cite":"547 U.S. 189","y":2006,"id":"2005/04-1618","sc":1,"by":{"3":"5"}},{"t":"case","label":"Shelton v. United States","cite":"327 F.2d 601","y":1963,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/327/601/","by":{"3":"32"}},{"t":"case","label":"Shelton v. United States","cite":"404 F.2d 1292","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/404/1292/","by":{"3":"17"},"q":[{"src":"brief","b":3,"text":"the mere assertion of a need to consider ‘remedial legislation,’","cite":"404 F.2d 1292, 1297"}]},{"t":"case","label":"United States v. AT&T","cite":"567 F.2d 121","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/567/121/","by":{"3":"7"}},{"t":"case","label":"Vt. Agency of Natural Resources v. U.S. ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"by":{"3":"5"},"q":[{"src":"brief","b":3,"text":"in the period immediately before and after the framing of the Constitution.","cite":"529 U.S. 765, 776"}]},{"t":"const","label":"Article I, Section 2","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"by":{"3":"21"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"3":"6"}}]};